  "issue_resolution": [
    {
      "issue_id": "INDEPENDENT_0",
      "changed_target_ids": ["PROC_RELAXATION"],
      "reason": "Clarified that the neural-off route is the modelled normal relaxation pathway; ATP-depletion/fatigue remains an explicit exception and is not conflated with normal relaxation. The process no longer asserts the neuronal-off route as the sole possible termination.",
      "evidence_ids": ["E_d6fd3723dbb7"]
    },
    {
      "issue_id": "INDEPENDENT_1",
      "changed_target_ids": [],
      "reason": "No process/relation fields were updated for this issue because the mislocated state subject (ENT_SR vs sarcoplasm) cannot be corrected within the allowed process/relation field set; ST_CA_IN_SARCOPLASM remains with subject_ref ENT_SR as an SR Ca2+-location change. The issue is noted but not resolved by this patch.",
      "evidence_ids": ["E_d6fd3723dbb7"]
    },
    {
      "issue_id": "INDEPENDENT_2",
      "changed_target_ids": ["REL_CA_TO_TROPONIN_TROPOMYOSIN"],
      "reason": "Relation source changed to ENT_TROPONIN_TROPOMYOSIN and target to ENT_ACTIN_MYOSIN_SARCOMERE, so the source now matches the actor binding Ca2+ and the target is the actin site whose exposure changes, consistent with the quote.",
      "evidence_ids": ["E_d6fd3723dbb7"]
    },
